(function(){
 'use strict';
 const E=MathEngine,$=s=>document.querySelector(s),app=$('#app'),KEY='mathelio.state.v1';
 const schoolTracks={junior:'CP',ce1:'CE1',ce2:'CE2',cm1:'CM1',cm2:'CM2',sixieme:'6e'};
 // The first six IDs are preserved for existing and portable profiles.
 const avatars=[['🦊','Renard','renard'],['🐱','Chat','chat'],['🐲','Dragon','dragon'],['🤖','Robot','petit_robot'],['🐼','Panda','panda'],['🐱','Chat','chat'],['🐢','Tortue','tortue'],['🦉','Hibou','hibou'],['🐸','Grenouille','grenouille'],['🐰','Lapin','lapin'],['🐙','Poulpe','poulpe'],['🦁','Lionceau','lionceau'],['🐧','Pingouin','pingouin'],['🦕','Petit dinosaure','petit_dinosaure'],['👻','Petit fantôme','petit_fantome'],['🦄','Licorne','licorne'],['🐉','Dragon chinois','dragon_chinois'],['🦝','Raton laveur','raton_laveur'],['🐨','Koala','koala'],['🐺','Petit loup','petit_loup']];
 const accessories=[['casquette','Casquette rouge'],['magicien','Chapeau de magicien'],['couronne','Couronne royale'],['bonnet','Bonnet à pompon'],['casque','Casque musical'],['haut-de-forme','Haut-de-forme'],['masque','Masque de héros'],['fete','Chapeau de fête'],['lunettes','Lunettes rondes'],['lunettes-etoiles','Lunettes étoilées'],['echarpe','Écharpe rayée'],['noeud','Nœud papillon'],['moustache','Moustache'],['oreilles-lapin','Oreilles de lapin'],['couronne-fleurs','Couronne de fleurs'],['casquette-helice','Casquette à hélice'],['cache-oeil','Cache-œil de pirate'],['aureole','Auréole dorée']];
 const badgeDefs=[['first','🚀','Premier envol','Terminer une première partie.',s=>s.sessions,1],['streak','🎯','Dans le mille','Réussir 10 réponses de suite.',s=>s.bestStreak,10],['repair','🔧','Erreur réparée','Corriger un calcul précédemment raté.',s=>s.repairs,1],['explore','🧭','Explorateur','Jouer avec les quatre opérations.',s=>s.ops.length,4],['table','✖️','Ami des tables','Réussir 20 calculs dans une même table.',s=>Math.max(0,...Object.values(s.tables)),20],['record','🌱','Je progresse','Améliorer un record en défi.',s=>s.records,1],['days','📅','Au rendez-vous','Jouer sur trois jours différents.',s=>s.days.length,3],['reviews','💪','Persévérant','Terminer trois révisions des erreurs.',s=>s.reviews,3],['fifty','✨','Cinquante soleils','Trouver 50 bonnes réponses.',s=>s.correct,50],['hundred','🌟','Constellation','Trouver 100 bonnes réponses.',s=>s.correct,100],['ten','🪐','Voyageur','Terminer 10 parties.',s=>s.sessions,10],['perfect','🏆','Sans faute','Réussir un défi à 10 sur 10.',s=>s.perfect,1]];
 const badgeAssets=['01_premier_envol', '02_dans_le_mille', '03_erreur_reparee', '04_explorateur', '05_ami_des_tables', '06_je_progresse', '07_au_rendez_vous', '08_perseverant', '09_cinquante_soleils', '10_constellation', '11_voyageur', '12_sans_faute', '13_table_de_2', '14_table_de_3', '15_table_de_4', '16_table_de_5', '17_table_de_6', '18_table_de_7', '19_table_de_8', '20_table_de_9', '21_table_de_10', '22_petit_explorateur', '23_le_compte_est_bon', '24_mission_accomplie'];
 const stats=()=>MathProgress.emptyStats();
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const id=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
 let state={version:1,active:null,profiles:[],scores:[]},view='home',game=null,last=null,toastTimer;
 let config={category:'add',level:'easy',mode:'practice',table:'',track:'cm1',count:10};
 let starting=false,apiPending=false,doomUnlocked=false,logoClicks=0,lastLogoClick=0;
 const P=MathProgress,A=MathAudio,N=NumberDisplay,L=MathLearning;
 const credentials=()=>{try{return JSON.parse(localStorage.getItem('mathelio.credentials.v1')||'{}');}catch{return {};}};
 const auth={...credentials()};
 function saveAuth(){try{localStorage.setItem('mathelio.credentials.v1',JSON.stringify(auth));}catch{toast('Identité commune temporaire : stockage indisponible.');}}
 async function api(route,data,player=profile()){const res=await fetch('api/'+route,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',...(auth[player?.id]?{Authorization:'Bearer '+auth[player.id]}:{})},...(data?{body:JSON.stringify(data)}:{}),signal:AbortSignal.timeout(10000)});let body;try{body=await res.json();}catch{throw Error('Classement commun indisponible. Le serveur doit être installé sur le LXC.');}if(!res.ok){if(res.status===401&&player){delete auth[player.id];saveAuth();}throw Error(body.error||'Serveur indisponible');}return body;}

 function validProfile(p){return p&&typeof p.id==='string'&&typeof p.name==='string'&&p.name.length<=24&&Number.isInteger(p.avatar)&&p.avatar>=0&&p.avatar<avatars.length&&Number.isFinite(p.stars)&&p.stars>=0&&Array.isArray(p.badges)&&p.badges.every(x=>typeof x==='string')&&p.stats&&['sessions','bestStreak','repairs','records','reviews','correct','perfect'].every(k=>Number.isFinite(p.stats[k])&&p.stats[k]>=0)&&Array.isArray(p.stats.ops)&&Array.isArray(p.stats.days)&&p.stats.tables&&typeof p.stats.tables==='object'&&Object.values(p.stats.tables).every(Number.isFinite)&&Array.isArray(p.errors)&&p.errors.every(q=>q&&['add','sub','mul','div'].includes(q.op)&&[q.a,q.b,q.answer].every(Number.isFinite)&&typeof q.label==='string')&&(p.accessory===null||(Number.isInteger(p.accessory)&&p.accessory>=0&&p.accessory<(p.cosmeticsVersion===2?accessories.length:12)&&p.stars>=(p.accessory+1)*10));}
 try {const raw=localStorage.getItem(KEY);if(raw){const s=JSON.parse(raw);if(s.version!==1||!Array.isArray(s.profiles)||!s.profiles.every(validProfile)||!Array.isArray(s.scores)||!s.scores.every(x=>x&&typeof x.profile==='string'&&typeof x.name==='string'&&Number.isFinite(x.score)&&Number.isFinite(x.correct)&&Number.isFinite(x.duration)&&Object.hasOwn(E.categories,x.category)&&Object.hasOwn(E.levels,x.level)&&typeof x.date==='string'))throw Error('Format de sauvegarde non reconnu');state=s;state.profiles=state.profiles.map(p=>({...P.cleanProfile({...p,records:p.records||state.scores.filter(x=>x.profile===p.id)}),shared:p.shared===true}));if(!state.profiles.some(p=>p.id===state.active))state.active=state.profiles[0]?.id||null;}}
 catch(e){AppLog.log('error','Lecture de la sauvegarde impossible',e.message);$('#storage-warning').hidden=false;$('#storage-warning').textContent='La sauvegarde est illisible ou inaccessible. Une session temporaire est ouverte ; les données existantes sont conservées.';state={version:1,active:null,profiles:[],scores:[],readOnly:true};}
 for(const p of state.profiles){p.stats={...P.emptyStats(),...p.stats};p.history??=[];p.records??=state.scores.filter(s=>s.profile===p.id).map(s=>({...s,track:s.track||'cm1'}));p.mission=P.cleanMission(p.mission);p.errors=p.errors.map(q=>P.cleanQuestion(q));}
 function save(){if(state.readOnly)return false;try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch(e){$('#storage-warning').hidden=false;AppLog.log('error','Échec de sauvegarde',e.message);return false;}}
 const profile=()=>state.profiles.find(p=>p.id===state.active);
 let preferenceOwner=null;
 function activateProfile(){const p=profile();if(preferenceOwner!==p?.id){preferenceOwner=p?.id;config.track=p?.track||'cm1';config.category='add';config.table='';}N.activate(p,save);L.activate(p,save);}
 function chooseTrack(track){config.track=track;const p=profile();if(p){p.track=track;save();}}
 function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
 function avatarImage(index,animated=false){const [emoji,name,sprite]=avatars[index];return sprite?(animated?`<span class="avatar-sprite avatar-${sprite}" aria-hidden="true"></span>`:`<img class="avatar-thumbnail" src="assets/avatars/${sprite}/${sprite==='chat'?'portrait':'0'}.png" width="72" height="72" alt="" loading="lazy">`):`<span class="avatar-emoji" aria-hidden="true">${emoji}</span>`;}
 function accessoryImage(index){return `<img class="accessory-thumbnail" src="assets/accessories/${accessories[index][0]}/icon.png" width="80" height="80" alt="" loading="lazy">`;}
 function portrait(p){const sprite=avatars[p.avatar][2],equipped=p.accessory!==null,item=equipped?accessories[p.accessory]:null;return `<span class="portrait ${equipped?`portrait-equipped item-${item[0]} ${sprite?'avatar-portrait-'+sprite:''}`:''}" role="img" aria-label="${avatars[p.avatar][1]}${equipped?', '+item[1]:''}">${sprite&&equipped?`<span class="avatar-sprite avatar-${sprite}" style="background-image:url('assets/avatars/${sprite}/equipped.png')" aria-hidden="true"></span><span class="avatar-sprite avatar-${sprite} accessory-layer" style="background-image:url('assets/accessories/${item[0]}/${sprite}.png')" aria-hidden="true"></span>`:avatarImage(p.avatar,true)}${!sprite&&equipped?`<img class="emoji-accessory emoji-accessory-${item[0]}" src="assets/accessories/${item[0]}/icon.png" alt="">`:''}</span>`;}
 function head(title,sub){return `<h1>${title}</h1><p class="subtitle">${sub}</p>`;}
 function selectOptions(values,selected){return Object.entries(values).map(([k,v])=>`<option value="${k}" ${k===selected?'selected':''}>${v}</option>`).join('');}
 function setView(next){if(starting||apiPending)return;if(game&&view==='game'&&next!=='game'){if(!confirm('Quitter cette partie ? Elle ne sera pas enregistrée.'))return;game=null;}if(next!=='doom'&&next!=='game'&&next!=='results')A.exitDoom();view=next;if(['home','minigames','collection','records','parent','settings','profiles'].includes(next))history.replaceState(null,'','#'+next);document.querySelectorAll('.parent-navigation[open]').forEach(el=>el.open=false);render();window.scrollTo({top:0,behavior:'instant'});}
 function render(){activateProfile();L.apply();document.body.classList.toggle('learning-playing',view==='game');document.body.classList.toggle('doom-theme',view==='doom'||(view==='game'&&game?.config.track==='doom')||(view==='results'&&last?.config.track==='doom'));app.focus({preventScroll:true});document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#profile-nav').textContent=profile()?`${avatars[profile().avatar][0]} ${profile().name}`:'Mon profil';if(!profile()&&!['profiles','minigames'].includes(view))view='profiles';({home:home,minigames:miniMenu,profiles:profiles,collection:collection,records:records,game:renderGame,results:results,settings:settings,parent:parent,adventures:adventures,doom:doom})[view]();}
 function miniMenu(){app.innerHTML=MiniGameMenu.html();MiniGameMenu.bindFilters(app);app.querySelectorAll('[data-mini]').forEach(link=>link.onclick=e=>{e.preventDefault();const entry=MiniGameMenu.entries.find(x=>x[0]===link.dataset.mini);if(!entry)return;app.innerHTML='<button id="mini-close">← Tous les mini-jeux</button><iframe class="mini-frame" title="'+escape(entry[1])+'" src="about:blank"></iframe>';const frame=app.querySelector('iframe'),url=new URL(entry[4],location.href);url.searchParams.set('embedded','1');if(link.dataset.daily)url.searchParams.set('daily','1');url.searchParams.set('level',MiniProgress.levels[link.dataset.level]?link.dataset.level:config.track==='junior'?'cp':config.track);frame.src=url.href;window.MathelioAnalytics?.openGame(entry[0]);$('#mini-close').onclick=()=>{frame.contentWindow?.speechSynthesis?.cancel();miniMenu();};});}
 window.MiniProfilePortrait=()=>profile()?portrait(profile()):'';
 function home(){if(L.prefs.calm)config.mode='practice';const p=profile(),next=Math.min(accessories.length*10,(Math.floor(p.stars/10)+1)*10);app.innerHTML=`${head(`Prêt pour l’aventure en ${schoolTracks[config.track]||'CM1'}, ${escape(p.name)} ?`,'Choisis ton terrain de jeu. Chaque calcul te fait avancer.')}${adventureCard()}<section class="panel fields-home-card"><div><h2>✦ Les mini-jeux</h2><p>Champs, tours, courses et petits ateliers : choisis ton jeu.</p></div><a class="primary fields-link" href="index.html#minigames" data-view="minigames">Choisir un mini-jeu →</a></section><div class="layout"><section class="panel setup" aria-label="Configurer ma partie"><div class="formrow"><label>Ton parcours<select id="track">${selectOptions(schoolTracks,config.track)}</select></label>${config.mode==='practice'?`<label>Questions<select id="count">${[5,10,20].map(n=>`<option value="${n}" ${config.count===n?'selected':''}>${n}</option>`).join('')}</select></label>`:''}</div>${suggestion(p)}<div><p class="section-label"><span class="step">1</span> Avec quoi veux-tu jouer ?</p><div class="choices">${Object.entries(config.track==='junior'?{add:'Additions',sub:'Soustractions',mix:'Mode mixte'}:E.categories).map(([k,v],i)=>`<button class="choice ${config.category===k?'selected':''}" data-category="${k}" aria-pressed="${config.category===k}"><span class="symbol">${{add:'+',sub:'−',mul:'×',div:'÷',mix:'✳'}[k]}</span>${v}</button>`).join('')}</div></div><div><p class="section-label"><span class="step">2</span> Choisis ton niveau</p><div class="choices levels">${Object.entries(E.levels).map(([k,v],i)=>`<button class="choice ${config.level===k?'selected':''}" data-level="${k}" aria-pressed="${config.level===k}">${['🌱','🌿','🌳'][i]} ${v}<small>${['Je prends confiance','Je me dépasse','Je relève le défi'][i]}</small></button>`).join('')}</div><p class="muted" style="font-size:13px;margin-bottom:0">${['ce1','ce2'].includes(config.track)?E.schoolHelp[config.track][config.level]:config.track==='sixieme'?(config.level==='easy'?'Décimaux au dixième, multiplier et diviser par 10, 100 et 1 000.':config.level==='medium'?'Décimaux au centième, nombre entier moins un décimal, décimal multiplié ou divisé par un nombre entier.':'Ordre des opérations : la multiplication avant l’addition, les parenthèses d’abord.'):config.track==='cm2'?(config.level==='easy'?'Calculs jusqu’à 3 000, multiplications à deux chiffres et divisions exactes.':config.level==='medium'?'Calculs au dixième, produits et divisions avec des nombres plus grands.':'Calculs au centième, multiplications de deux nombres à deux chiffres et divisions exactes.'):config.track==='junior'?(config.category==='sub'?(config.level==='easy'?'Enlève un nombre, jusqu’à 10.':config.level==='medium'?'Soustractions jusqu’à 18.':'Soustractions jusqu’à 19.'):config.category==='mix'?'Alterner additions et soustractions ; au niveau difficile, aussi des compléments à 20.':config.level==='easy'?'Additionne deux chiffres pour un total jusqu’à 10.':config.level==='medium'?'Additionne deux chiffres pour un total entre 10 et 18.':'Trouve le nombre manquant pour arriver à 20.'):config.level==='easy'?'Petits nombres, sans retenue. Tables de 2, 5 et 10.':config.level==='medium'?'Calculs avec retenue. Tables de 2 à 9.':'Additions et soustractions au dixième. Tables de 11, 12, 15, 20 et 25.'}</p>${['mul','div'].includes(config.category)?`<label class="spaced">Une table en particulier ?<select id="table"><option value="">Toutes les tables du niveau</option>${Array.from({length:['ce1','ce2'].includes(config.track)?9:11},(_,i)=>i+2).map(n=>`<option ${config.table===String(n)?'selected':''} value="${n}">Table de ${n}</option>`).join('')}</select></label>`:''}</div><div><p class="section-label"><span class="step">3</span> À ton rythme ou pour le record ?</p><div class="choices modes"><button class="choice mode ${config.mode==='practice'?'selected':''}" data-mode="practice" aria-pressed="${config.mode==='practice'}"><strong>☀ Entraînement</strong><small>Prends ton temps, essaie et apprends.</small></button><button class="choice mode ${config.mode==='challenge'?'selected':''}" data-mode="challenge" aria-pressed="${config.mode==='challenge'}"><strong>⚡ Défi</strong><small>Vise juste et bats ton record !</small></button></div></div><div><button id="start" class="primary start">C’est parti !</button><p class="hint">${config.mode==='challenge'?10:config.count} questions · ${config.mode==='practice'?(L.prefs.calm?'Mode calme · passage manuel':'Sans chronomètre'):config.track==='junior'?'Sans bonus de rapidité':'Bonus de vitesse limité à 20 points'} · Des étoiles à gagner</p></div></section><aside class="aside">${missionCard(p)}<section class="panel companion"><p class="eyebrow">Ton compagnon d’aventure</p><div class="orbit">${portrait(p)}</div><h2>${escape(p.name)}</h2><p>Explorateur · Niveau ${Math.floor(p.stars/10)+1}</p><div class="starline"><strong>⭐ ${p.stars} étoiles</strong><span>${p.stars>=accessories.length*10?'Collection complète':`${next} à atteindre`}</span></div><div class="progress"><span style="width:${p.stars>=accessories.length*10?100:p.stars%10*10}%"></span></div><p style="font-size:13px">${p.stars>=accessories.length*10?'Tous tes accessoires sont disponibles !':`Encore ${next-p.stars} étoile${next-p.stars>1?'s':''} pour un accessoire.`}</p><button data-view="collection">Personnaliser mon compagnon</button></section><section class="panel small-panel"><h3>✦ Tes petits grands progrès</h3><div class="statrow"><div class="stat"><strong>${p.stats.sessions}</strong><span>parties jouées</span></div><div class="stat"><strong>${p.badges.length}/${badgeDefs.length}</strong><span>badges gagnés</span></div></div></section>${p.errors.length?`<section class="panel small-panel"><h3>🔧 À toi de réessayer</h3><p>${p.errors.length} calcul${p.errors.length>1?'s':''} à revoir au fil de tes séances.</p><button id="review-home" class="wide spaced">Revoir mes erreurs</button></section>`:''}</aside></div>`;
 $('#track').value=config.track;$('#track').onchange=e=>{chooseTrack(e.target.value);config.category='add';config.table='';config.count=config.track==='junior'?5:10;home();};if($('#count'))$('#count').onchange=e=>config.count=Number(e.target.value);if($('#suggest-level'))$('#suggest-level').onclick=()=>{config.level=$('#suggest-level').dataset.level;home();};app.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{config.category=b.dataset.category;config.table='';home();});app.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{config.level=b.dataset.level;home();});app.querySelectorAll('[data-mode]').forEach(b=>{if(L.prefs.calm&&b.dataset.mode==='challenge'){b.disabled=true;b.title='Désactive le mode calme dans Réglages pour jouer en défi.';}b.onclick=()=>{config.mode=b.dataset.mode;home();};});if($('#table'))$('#table').onchange=e=>config.table=e.target.value;$('#start').onclick=()=>start();bindDaily();bindMission();if($('#review-home'))$('#review-home').onclick=()=>start(profile().errors);}
 function profiles(){const p=profile();app.innerHTML=`${head(p?(document.body.classList.contains('who-plays')?'Qui joue ?':'Ton équipe d’explorateurs'):'Bienvenue dans Mathélio !',p?'Chacun son compagnon, ses étoiles et ses records.':'Choisis un compagnon et un pseudo pour commencer.')}<section class="panel"><h2>${p?'Changer de profil':'Crée ton premier profil'}</h2>${state.profiles.length?`<div class="actions" style="justify-content:start">${state.profiles.map(x=>`<button data-profile="${escape(x.id)}" class="who-button ${x.id===state.active?'primary':''}"><span class="who-face" aria-hidden="true">${avatarImage(x.avatar)}</span><span class="who-name">${escape(x.name)}</span><small>${x.stars} ⭐</small></button>`).join('')}</div>`:''}<form id="profile-form"><div class="formrow"><label>Pseudo<input id="name" maxlength="24" required autocomplete="off" placeholder="Ton prénom ou un surnom"></label><label>Ton niveau<select id="profile-track">${selectOptions(schoolTracks,'junior')}</select></label></div><p class="section-label">Ton premier compagnon</p><div class="avatar-options">${avatars.map(([emoji,name],i)=>i===5?'':`<button type="button" class="selectable ${i===0?'selected':''}" ${i>6?'hidden':''} data-avatar="${i}" aria-pressed="${i===0}">${avatarImage(i)}<small>${name}</small></button>`).join('')}</div><button id="all-companions" type="button" aria-expanded="false">Voir tous les compagnons</button><button class="primary profile-create" type="submit">Créer mon profil</button></form><p class="muted">Les profils restent dans ce navigateur. Tu peux choisir un surnom.</p></section>`;let chosen=0;$('#all-companions').onclick=()=>{const button=$('#all-companions'),expanded=button.getAttribute('aria-expanded')==='true';app.querySelectorAll('[data-avatar]').forEach(el=>el.hidden=expanded&&Number(el.dataset.avatar)>6);button.setAttribute('aria-expanded',String(!expanded));button.textContent=expanded?'Voir tous les compagnons':'Voir moins de compagnons';};app.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>{chosen=Number(b.dataset.avatar);app.querySelectorAll('[data-avatar]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b);});});app.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{state.active=b.dataset.profile;save();document.body.classList.remove('who-plays');try{sessionStorage.setItem('mathelio.chosen','1');}catch{}view='home';history.replaceState(null,'','#home');render();window.scrollTo({top:0,behavior:'instant'});});$('#profile-form').onsubmit=e=>{e.preventDefault();const name=$('#name').value.trim();if(!name){$('#name').setCustomValidity('Choisis un pseudo.');$('#name').reportValidity();return;}if(state.profiles.length>=12){toast('12 profils maximum sur cet appareil.');return;}const p={id:id(),name,track:$('#profile-track').value,avatar:chosen,cosmeticsVersion:2,accessory:null,stars:0,badges:[],stats:stats(),errors:[],history:[],records:[],mission:P.cleanMission(null)};state.profiles.push(p);state.active=p.id;save();view='home';history.replaceState(null,'','#home');render();window.scrollTo({top:0,behavior:'instant'});};$('#name').oninput=e=>e.target.setCustomValidity('');}
 function collection(){const p=profile();app.innerHTML=`${head('Ta collection','Des souvenirs de tes progrès, à porter fièrement.')}<div class="layout"><div><section class="panel"><h2>Choisis ton compagnon</h2><div class="avatar-options">${avatars.map(([emoji,name],i)=>i===5?'':`<button class="selectable ${p.avatar===i?'selected':''}" data-avatar="${i}" aria-pressed="${p.avatar===i}">${avatarImage(i)}<small>${name}</small></button>`).join('')}</div><h2 class="spaced">Les accessoires <small class="muted">${Math.min(accessories.length,Math.floor(p.stars/10))}/${accessories.length}</small></h2><button id="no-accessory">Sans accessoire</button><div class="grid spaced">${accessories.map(([asset,name],i)=>`<div class="accessory-choice"><button class="badge ${p.accessory===i?'selected selectable':''}" data-accessory="${i}" aria-pressed="${p.accessory===i}" ${p.stars<(i+1)*10?'disabled':''}>${accessoryImage(i)}${name}<span class="tag">${p.stars<(i+1)*10?`${(i+1)*10} étoiles`:'Disponible'}</span></button><button type="button" data-preview="${i}">Essayer ${name}</button></div>`).join('')}</div></section></div><aside class="panel companion"><p class="eyebrow">C’est tout toi !</p><div class="orbit">${portrait(p)}</div><h2>${escape(p.name)}</h2><p>⭐ ${p.stars} étoiles</p><p>Un nouvel accessoire toutes les 10 étoiles.</p>${p.stars<accessories.length*10?`<div class="next-reward"><p>Prochaine récompense</p>${accessoryImage(Math.floor(p.stars/10))}<strong>${accessories[Math.floor(p.stars/10)][1]}</strong><p>Encore ${(Math.floor(p.stars/10)+1)*10-p.stars} étoiles.</p></div>`:''}<p id="accessory-preview-status" role="status"></p></aside></div><h2 class="spaced">Tes badges · ${p.badges.length}/${badgeDefs.length}</h2><div class="grid badge-grid">${badgeDefs.map(([id,emoji,title,desc,value,target],index)=>`<article data-badge-order="${index}" data-badge-progress="${Math.min(1,value(p.stats)/target)}" class="panel badge ${p.badges.includes(id)?'':'locked'}"><span class="badge-icon badge-picture"><img src="assets/badges/${badgeAssets[index]}.png" width="96" height="96" alt="" loading="lazy">${p.badges.includes(id)?'':'<span class="badge-lock" aria-hidden="true">🔒</span>'}</span><h3>${title}</h3><p>${desc}</p><span class="tag">${p.badges.includes(id)?'✓ Gagné !':`${Math.min(target,value(p.stats))} / ${target}`}</span></article>`).join('')}</div>${trophies(p)}`;app.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>{p.avatar=Number(b.dataset.avatar);save();render();});app.querySelectorAll('[data-accessory]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.accessory);if(p.stars>=(i+1)*10){p.accessory=i;save();render();}});app.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.preview);app.querySelector('.companion .orbit').innerHTML=portrait({...p,accessory:i});$('#accessory-preview-status').textContent='Aperçu : '+accessories[i][1]+'. '+(p.stars<(i+1)*10?'À débloquer à '+((i+1)*10)+' étoiles.':'Clique sur l’accessoire pour le porter.');});const badgeGrid=app.querySelector('.badge-grid');if(badgeGrid){const label=document.createElement('label');label.className='badge-sort';label.innerHTML='Afficher les badges<select id="badge-order"><option value="all">Tous les badges</option><option value="next">Mes prochains badges</option><option value="earned">Mes badges gagnés</option></select>';badgeGrid.prepend(label);const status=document.createElement('p');status.className='badge-filter-status';status.setAttribute('role','status');status.hidden=true;label.after(status);label.querySelector('select').onchange=e=>{const cards=[...badgeGrid.querySelectorAll('[data-badge-order]')],mode=e.target.value;cards.sort((a,b)=>mode==='next'?Number(b.dataset.badgeProgress)-Number(a.dataset.badgeProgress):Number(a.dataset.badgeOrder)-Number(b.dataset.badgeOrder));cards.forEach(card=>{card.hidden=mode==='next'?!card.classList.contains('locked'):mode==='earned'?card.classList.contains('locked'):false;badgeGrid.append(card);});status.hidden=cards.some(card=>!card.hidden);status.textContent=mode==='earned'?'Ton premier badge t’attend : termine une séance pour commencer.':'Tous tes badges sont déjà gagnés !';};}$('#no-accessory').onclick=()=>{p.accessory=null;save();render();};}
 function records(){
  let scope='personal',request=0;
  app.innerHTML=`${head('Le tableau des records','Un défi à la fois, à ton rythme.')}<section class="panel"><div class="actions"><button id="personal" class="primary" aria-pressed="true">Mes records</button><button id="common" aria-pressed="false">Classement commun</button></div><div class="formrow"><label>Parcours<select id="record-track">${selectOptions(schoolTracks,config.track)}${doomUnlocked||profile().records.some(r=>r.track==='doom')?'<option value="doom">Doom · Extrême</option>':''}</select></label><label>Opération<select id="record-category">${selectOptions(E.categories,config.category)}</select></label><label>Difficulté<select id="record-level">${selectOptions(E.levels,config.level)}</select></label><label>Table<select id="record-table"><option value="">Toutes les tables du niveau</option>${Array.from({length:['ce1','ce2'].includes(config.track)?9:11},(_,i)=>i+2).map(n=>`<option value="${n}">Table de ${n}</option>`).join('')}</select></label></div><div id="record-list" aria-live="polite"></div><p class="muted" id="record-help"></p></section>`;
  $('#record-track').value=last?.config.track==='doom'?'doom':config.track;
  async function list(){const serial=++request,track=$('#record-track').value;const cat=track==='doom'?'mix':track==='junior'&&!['add','sub','mix'].includes($('#record-category').value)?'add':$('#record-category').value;if(track==='doom')$('#record-level').value='hard';$('#record-level').disabled=track==='doom';$('#record-category').innerHTML=selectOptions(track==='junior'?{add:'Additions',sub:'Soustractions',mix:'Mode mixte'}:E.categories,cat);$('#record-category').disabled=track==='doom';const useTable=['ce1','ce2','cm1','cm2','sixieme'].includes(track)&&['mul','div'].includes(cat);const previousTable=$('#record-table').value;$('#record-table').innerHTML='<option value="">Toutes les tables du niveau</option>'+Array.from({length:['ce1','ce2'].includes(track)?9:11},(_,i)=>i+2).map(n=>`<option value="${n}">Table de ${n}</option>`).join('');$('#record-table').value=['ce1','ce2'].includes(track)&&Number(previousTable)>10?'':previousTable;$('#record-table').disabled=!useTable;if(!useTable)$('#record-table').value='';const cfg={track,category:cat,level:$('#record-level').value,table:$('#record-table').value};$('#record-list').textContent='Chargement…';$('#record-help').textContent=scope==='common'?'Un meilleur résultat par identité locale et par réglage. Participation facultative dans les réglages.':'Les dix meilleurs défis du profil actif. Aucun temps de lecture ou de pause ne compte.';
   try {const scores=scope==='common'?(await api('scores?'+new URLSearchParams(cfg))).scores:profile().records.filter(s=>(s.track||'cm1')===track&&s.category===cat&&s.level===cfg.level&&(s.table||'')===cfg.table).sort(rank).slice(0,10).map(s=>({...s,name:profile().name}));if(view!=='records'||serial!==request)return;
    $('#record-list').innerHTML=scores.length?`<div class="table-wrap"><table><thead><tr><th>Place</th><th>Explorateur</th><th>Score</th><th>Réussite</th><th>Temps</th><th>Date</th></tr></thead><tbody>${scores.map((s,i)=>`<tr><td>${i+1}</td><td>${escape(s.name)}</td><td>${s.score}</td><td>${s.correct}/10</td><td>${Math.round(s.duration)} s</td><td>${new Date(s.date).toLocaleDateString('fr-FR')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Le premier record t’attend ! Termine un défi avec ces réglages.</p>';
   }catch(e){if(view==='records'&&serial===request)$('#record-list').textContent=e.message;}}
  for(const key of ['track','category','level','table'])$('#record-'+key).onchange=list;
  for(const [id,value]of [['personal','personal'],['common','common']])$('#'+id).onclick=()=>{scope=value;for(const k of ['personal','common']){$('#'+k).classList.toggle('primary',k===id);$('#'+k).setAttribute('aria-pressed',k===id);}list();};list();
 }
 function rank(a,b){return b.score-a.score||b.correct-a.correct||a.duration-b.duration;}
 async function start(review,override){
  if(starting)return;starting=true;if($('#start'))$('#start').disabled=true;
  try {const c=L.configure(override||config);if(review||c.activity)c.mode='practice';let questions=review?review.filter(q=>(q.track||'cm1')===c.track).slice(0,20).map(q=>({...q})):c.activity==='daily'?P.daily(profile(),c,E):E.generate(c);if(!questions.length){toast('Aucun calcul à revoir pour ce parcours.');return;}
   if(c.activity==='coop'){const partner=state.profiles.find(p=>p.id===c.partner);if(!partner||partner.id===profile().id){toast('Choisis un deuxième profil.');return;}const other=E.generate({...c,track:c.partnerTrack,level:c.partnerLevel,count:5,category:'mix',table:''});questions=questions.slice(0,5).flatMap((q,i)=>[{...q,player:profile().id},{...other[i],player:partner.id}]);}
   if(c.activity==='stories')questions=questions.map(q=>({...q,story:true}));
   let remote=null;if(c.mode==='challenge'&&profile().shared){const data=await api('games',{config:c,name:profile().name});remote=data.game;questions[0]=data.question;}
   if(c.mode==='practice'&&!review&&!c.activity){const due=P.due(profile(),c.track).filter(q=>(c.category==='mix'||q.op===c.category)&&q.level===c.level);const unscheduled=profile().errors.filter(q=>!(profile().reviews||[]).some(r=>P.key(r)===P.key(q))&&q.track===c.track&&(c.category==='mix'||q.op===c.category)&&q.level===c.level);if(due.length||unscheduled.length)questions[0]={...(due[0]||unscheduled[0])};}
   game={config:c,questions,index:0,answers:[],score:0,combo:0,maxCombo:0,review:!!review,paused:false,elapsed:0,tick:performance.now(),tries:0,feedback:null,first:null,repaired:[],done:false,correctionIndex:0,remote,autoRemaining:5000,scheduled:new Set()};A.startGame(c.track);view='game';render();
  }catch(e){toast(e.message);AppLog.log('warning','Démarrage du défi impossible',e.message);}finally{starting=false;if($('#start'))$('#start').disabled=false;}
 }
 function adventureCard(){return `<section class="panel adventure-card"><div><p class="eyebrow">De nouvelles aventures</p><h2>☀ Ma séance du jour</h2><p>Cinq calculs pour revoir, consolider et découvrir, à ton rythme.</p></div><div class="actions"><button id="daily-start" class="primary">Commencer mes 5 calculs</button><button data-view="adventures">Carte, histoires et coopération</button></div></section>`;}
 function adventures(){
  const p=profile(),due=P.due(p,config.track).length;
  app.innerHTML=`${head('Choisis ton aventure','Un petit pas chaque jour, et des aventures à partager.')}<section class="panel"><div class="formrow"><label>Mon parcours<select id="adventure-track">${selectOptions(schoolTracks,config.track)}</select></label><label>Mon niveau<select id="adventure-level">${selectOptions(E.levels,config.level)}</select></label></div><div class="adventure-grid spaced"><article><h2>☀ Ma séance du jour</h2><p>Cinq calculs : jusqu’à deux révisions, deux acquis à consolider et une découverte. ${due?`${due} révision(s) prête(s) aujourd’hui.`:'Les révisions reviendront quand le moment sera venu.'}</p><button id="daily-start" class="primary">Jouer ma séance</button></article><article><h2>📖 Petites histoires</h2><p>Résous cinq problèmes illustrés de récoltes, de paniers et de partages.</p><button id="stories-start">Ouvrir mon histoire</button></article><article><h2>🤝 Ensemble, on avance</h2><p>Dix questions à tour de rôle. Chacun joue à son niveau et cinq réponses réussies ensemble remplissent votre jauge.</p>${state.profiles.length>1?`<label>Mon partenaire<select id="coop-partner">${state.profiles.filter(x=>x.id!==p.id).map(x=>`<option value="${escape(x.id)}">${escape(x.name)}</option>`).join('')}</select></label><div class="formrow"><label>Son parcours<select id="coop-track">${selectOptions(schoolTracks,'junior')}</select></label><label>Son niveau<select id="coop-level">${selectOptions(E.levels,'easy')}</select></label></div><button id="coop-start" class="spaced">Jouer ensemble</button>`:'<p>Crée un deuxième profil pour jouer à deux.</p><button data-view="profiles">Créer un profil</button>'}</article></div></section><section class="panel spaced"><h2>🗺️ Ma carte des compétences · ${schoolTracks[config.track]}</h2><p>Chaque île reflète tes dix derniers essais. À partir de cinq essais et de 80 % de réussites sans indice, elle est bien consolidée. Tu peux toujours y retourner.</p><div class="skill-map">${P.skills(p,config.track).map(s=>`<button class="skill-island" data-skill="${s.id}"><span aria-hidden="true">${s.emoji}</span><strong>${s.title}</strong><small>${s.status}</small><span>${s.total?`${s.correct} / ${s.total} réussites autonomes`:'Première exploration'}</span></button>`).join('')}</div></section>`;
  $('#adventure-track').onchange=e=>{chooseTrack(e.target.value);config.category='mix';config.table='';adventures();};$('#adventure-level').onchange=e=>{config.level=e.target.value;adventures();};bindDaily();
  $('#stories-start').onclick=()=>start(null,{...config,activity:'stories',mode:'practice',category:'mix',table:'',count:5});
  if($('#coop-start'))$('#coop-start').onclick=()=>start(null,{...config,activity:'coop',mode:'practice',category:'mix',table:'',count:5,partner:$('#coop-partner').value,partnerTrack:$('#coop-track').value,partnerLevel:$('#coop-level').value});
  app.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{const skill=b.dataset.skill;let c={...config,mode:'practice',count:5,table:'',category:skill.startsWith('table')?'mul':skill==='complements'||skill==='doubles'?'add':skill};if(skill.startsWith('table'))c.table=skill.slice(5);if(skill==='complements')c.level='hard';if(skill==='complements'||skill==='doubles'){const questions=Array.from({length:5},(_,i)=>skill==='complements'?{op:'add',a:i+6,b:14-i,answer:14-i,complement:true,track:c.track,level:c.level,label:`${i+6} + ? = 20`}:c.track!=='junior'&&i%2?{op:'div',a:(i+2)*2,b:2,answer:i+2,track:c.track,level:c.level,label:`${(i+2)*2} ÷ 2`}:{op:'add',a:i+2,b:i+2,answer:(i+2)*2,track:c.track,level:c.level,label:`${i+2} + ${i+2}`});start(questions,{...c,activity:'island'});}else start(null,c);});
 }
 function bindDaily(){if($('#daily-start'))$('#daily-start').onclick=()=>start(null,{...config,category:'mix',table:'',activity:'daily',mode:'practice',count:5});}
 function finishCoop(g){
  const members=[profile(),state.profiles.find(p=>p.id===g.config.partner)];
  const summaries=members.map(p=>{const answers=g.answers.filter(a=>a.player===p.id),c={...g.config,track:answers[0].track,level:answers[0].level,category:'mix'};const progress=P.update(p,{...g,config:c,answers,maxCombo:0});const earned=3+(progress.correct/progress.total>=.8?1:0);p.stars+=earned;const badges=[];for(const [key,,title,,value,target]of badgeDefs)if(!p.badges.includes(key)&&value(p.stats)>=target){p.badges.push(key);badges.push(title);}return {name:p.name,...progress,earned,badges};});
  last={...g,coop:summaries};save();game=null;view='results';render();A.finish(summaries.some(s=>s.badges.length));
 }
 function coopResults(){const l=last,n=l.answers.filter(a=>a.corrected).length;app.innerHTML=`${head(n>=5?'🤝 Mission d’équipe réussie !':'🤝 Une belle aventure ensemble','Vous avez joué chacun à votre rythme.')}<section class="panel"><h2>${n} bonnes réponses ensemble sur 10</h2><p>Objectif commun : 5 réponses réussies, avec une seconde tentative possible.</p><div class="progress" role="progressbar" aria-label="Objectif commun" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${Math.min(5,n)}"><span style="width:${Math.min(100,n/5*100)}%"></span></div><div class="adventure-grid spaced">${l.coop.map(s=>`<article><h2>${escape(s.name)}</h2><p>${s.correct} / ${s.total} au premier essai · +${s.earned} étoiles</p>${s.badges.length?`<p>🏅 ${s.badges.map(escape).join(' · ')}</p>`:''}</article>`).join('')}</div><div class="actions"><button id="coop-replay" class="primary">Rejouer ensemble</button><button data-view="adventures">Mes aventures</button><button data-view="home">Accueil</button></div></section>`;$('#coop-replay').onclick=()=>start(null,l.config);}
 function seconds(){return (game.elapsed+(game.paused||game.done?0:performance.now()-game.tick))/1000;}
 function freeze(){if(game&&!game.paused){if(!game.done)game.elapsed+=performance.now()-game.tick;else if(game.autoTick)game.autoRemaining=Math.max(0,game.autoRemaining-(performance.now()-game.autoTick));game.paused=true;game.autoTick=null;}}
 function renderGame(){if(!game)return;const g=game,q=g.questions[g.index];L.apply();document.body.classList.add('learning-playing');app.innerHTML=`<section class="game ${q.track==='junior'?'junior':''}"><div class="game-head"><button type="button" class="quit-game" data-view="home" aria-label="Quitter la séance">✕</button>${g.questions.length<=20?`<div class="verre-steps" style="grid-template-columns:repeat(${g.questions.length},minmax(0,1fr))" role="img" aria-label="Question ${g.index+1} sur ${g.questions.length}">${g.questions.map((_,i)=>`<span class="${i<g.answers.length?(g.answers[i].correct?'done':'missed'):i===g.index?'now':''}"></span>`).join('')}</div>`:''}</div><div class="game-meta"><span>${g.config.track==='doom'?'🔥 DOOM · Extrême':g.config.activity?({daily:'☀ Ma séance du jour',stories:'📖 Petites histoires',coop:'🤝 Ensemble, on avance',island:'🗺️ Mon île'})[g.config.activity]:g.review?'Révision des erreurs':g.config.mode==='practice'?'☀ Entraînement':'⚡ Défi'} · ${g.review?'Tous niveaux':E.levels[q.level||g.config.level]}</span><button id="pause" ${g.config.track==='doom'&&!g.done?'disabled':''}>${g.paused?'Reprendre':'Pause'}</button></div><div class="progress"><span style="width:${g.index/g.questions.length*100}%"></span></div><div class="game-meta"><strong>Question ${g.index+1} sur ${g.questions.length}</strong><span>${g.config.mode==='challenge'?`<strong>${g.score} pts</strong> · Combo ${g.combo} ${g.config.track==='junior'?'':`· <span id="timer">${(g.config.track==='doom'?Math.max(0,30-seconds()):seconds()).toFixed(1)}</span> s${g.config.track==='doom'?' restantes':''}`}`:'Prends le temps de réfléchir'}</span></div><div class="panel game-card ${g.done?'answer-reviewed':''}">${g.paused?'<div class="pause"><div style="font-size:60px">☁️</div><h1>Petite pause</h1><p>On reprend quand tu veux.</p><button id="resume" class="primary">Reprendre la partie</button></div>':`<p class="eyebrow">${g.config.track==='doom'?'30 secondes. À vous de jouer.':g.review?'Une nouvelle chance !':'À toi de calculer'}</p>${g.config.activity==='coop'?`<h2>À ${escape(state.profiles.find(p=>p.id===q.player).name)} de jouer · ${schoolTracks[q.track]}</h2><p>🤝 ${Math.min(5,g.answers.filter(a=>a.corrected).length)} / 5 réussites pour l’équipe</p><progress aria-label="Objectif commun de cinq réussites" max="5" value="${Math.min(5,g.answers.filter(a=>a.corrected).length)}"></progress>`:''}${g.adaptiveNotice?`<p class="adaptive-notice" role="status">${g.adaptiveNotice}</p>`:''}${q.story?L.storyHtml(q):`<div class="calculation">${N.html(q.label)}${q.complement?'':g.done&&q.answer!==undefined?` = <span class="answer-slot filled">${N.html(E.fmt(q.answer))}</span>`:' = <span class="answer-slot" id="answer-slot" aria-hidden="true">?</span>'}</div>`}${g.config.activity==='coop'?'<p>Passez la main après chaque calcul.</p>':''}${N.legend(q.label)}${L.toolsHtml(q)}${g.config.mode==='practice'&&!g.done?`<section class="question-hints"><button id="question-hint" type="button" ${(g.hintIndex||0)>=L.hints(q).length?'disabled':''}>💡 ${(g.hintIndex||0)?'Un autre indice':'Un indice pour démarrer'}</button><p id="question-hint-text" role="status" tabindex="-1">${g.hintIndex?N.html(L.hints(q)[g.hintIndex-1]):''}</p></section>`:''}${q.track==='junior'?`<details class="count-help"><summary>Afficher les points pour compter</summary><p aria-label="${q.complement?20:q.a} points">${'● '.repeat(q.complement?20:q.a)}</p>${!q.complement?`<p class="dots-second" aria-label="${q.b} points à ${q.op==='sub'?'enlever':'ajouter'}">${q.op==='sub'?'−':'+'} ${'● '.repeat(q.b)}</p>`:''}</details>`:''}<form id="answer-form"><label for="answer" class="muted">Ta réponse</label><input class="answer" id="answer" inputmode="none" autocomplete="off" maxlength="9" aria-describedby="feedback" ${g.done?'disabled':''}><div id="answer-colors" class="answer-colors" aria-hidden="true"></div><div id="feedback-anchor"></div><div class="keypad ${Number.isInteger(q.answer)&&!String(q.label).includes(',')?'no-comma':''}">${['1','2','3','4','5','6','7','8','9',',','0','⌫'].filter(k=>k!==','||!(Number.isInteger(q.answer)&&!String(q.label).includes(','))).map(k=>`<button type="button" data-key="${k}" ${g.done?'disabled':''} aria-label="${k==='⌫'?'Effacer le dernier chiffre':k===','?'Virgule':k}">${k}</button>`).join('')}</div><button class="primary validate" ${g.done?'disabled':''}>Valider ma réponse</button></form><div id="feedback" aria-live="polite">${g.done&&L.prefs.steps&&g.config.track!=='doom'?`<div class="feedback ${g.first.correct?'good':'bad'}"><strong>${g.first.correct?'Bien joué !':'Prenons le temps de comprendre.'}</strong></div><div id="step-correction">${L.correctionHtml(q,g.correctionIndex||0)}</div>`:g.feedback||''}</div>${g.done&&!g.holdNext&&L.autoNext(A.prefs,g.config.track)?`<p id="countdown" class="hint">Suite dans ${Math.ceil(g.autoRemaining/1000)} s</p>`:''}${g.done&&!g.holdNext&&L.autoNext(A.prefs,g.config.track)?'<button id="hold-next" type="button" class="wide spaced">J’ai besoin de temps</button>':''}${g.done&&g.holdNext?'<p class="hint" role="status">Prends ton temps. Continue quand tu veux.</p>':''}${g.done?'<button id="next" class="primary wide spaced">'+(g.index===g.questions.length-1?'Voir mon bilan':'Question suivante')+'</button>':''}`}</div><p class="hint">${g.paused?'Le chronomètre est arrêté.':'Clavier : chiffres · Entrée pour valider · Retour arrière pour effacer'}</p></section>`;
 $('#pause').onclick=togglePause;if($('#resume'))$('#resume').onclick=togglePause;if(g.paused)return;
 L.bindTools(app,q,()=>{g.toolUsed=true;});if($('#question-hint'))$('#question-hint').onclick=()=>{g.input=$('#answer').value;g.hintIndex=(g.hintIndex||0)+1;renderGame();$('#question-hint-text').focus();};function bindCorrection(){for(const [id,delta] of [['correction-prev',-1],['correction-next',1]])if($('#'+id))$('#'+id).onclick=()=>{g.correctionIndex=Math.max(0,Math.min(L.correction(q).length-1,(g.correctionIndex||0)+delta));$('#step-correction').innerHTML=L.correctionHtml(q,g.correctionIndex);bindCorrection();$('#correction-text').focus();};}bindCorrection();const input=$('#answer');const colorAnswer=()=>{$('#answer-colors').innerHTML=N.prefs.enabled?N.html(input.value):'';if($('#place-table-content'))$('#place-table-content').innerHTML=L.tableHtml(q,input.value);};input.value=g.input||'';colorAnswer();N.decorate($('#feedback'));$('#feedback-anchor').replaceWith($('#feedback'));input.oninput=()=>{g.input=input.value;colorAnswer();};app.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{if(g.done)return;input.value=b.dataset.key==='⌫'?input.value.slice(0,-1):(input.value+b.dataset.key).slice(0,9);g.input=input.value;colorAnswer();input.focus({preventScroll:true});});$('#answer-form').onsubmit=e=>{e.preventDefault();submit();};if($('#show-answer'))$('#show-answer').onclick=()=>complete(false);if($('#hold-next'))$('#hold-next').onclick=()=>{g.holdNext=true;g.autoTick=null;renderGame();$('#next').focus();};if($('#next')){$('#next').onclick=next;$('#next').focus();}else input.focus({preventScroll:true});if(g.done||g.feedback){const feedback=$('#feedback');if(feedback){if(g.done)$('#next')?.focus({preventScroll:true});else input.focus({preventScroll:true});feedback.scrollIntoView({block:'nearest',behavior:'instant'});}}else $('.calculation,.story-problem')?.scrollIntoView({block:'nearest',behavior:'instant'});window.ScrollPrompt?.refresh();}
 async function togglePause(){if(!game||apiPending)return;const g=game;if(g.config.track==='doom'&&!g.done)return;apiPending=true;try{if(g.paused){if(g.remote&&!g.done)await api('games/'+g.remote+'/resume',{index:g.index});g.paused=false;g.tick=performance.now();g.autoTick=performance.now();}else{g.input=$('#answer')?.value||g.input;freeze();renderGame();if(g.remote&&!g.done)await api('games/'+g.remote+'/pause',{index:g.index});}renderGame();}catch(e){toast(e.message);}finally{apiPending=false;}}
 function tip(q){if(q.steps)return q.steps.join(' ');if(q.track==='doom')return 'Résous chaque parenthèse en partant de la plus intérieure.';if(q.complement)return `Pars de ${q.a} et compte jusqu’à 20 : il manque ${q.answer}.`;if(q.track==='junior'&&q.op==='sub')return `Compte ${q.a} points, puis enlève ${q.b} points. Il reste ${q.answer}.`;if(q.track==='junior')return `Compte ${q.a} points, puis ajoute ${q.b} points. Cela fait ${q.answer}.`;if(q.op==='add'){const rounded=Math.ceil(q.b/10)*10;return `Tu peux ajouter ${E.fmt(rounded)}, puis enlever ${E.fmt(Math.round((rounded-q.b)*100)/100)}.`;}if(q.op==='sub')return `Vérifie avec l’addition : ${E.fmt(q.answer)} + ${E.fmt(q.b)} = ${E.fmt(q.a)}.`;if(q.op==='mul')return `Décompose : ${E.fmt(q.a)} × ${Math.floor(q.b/10)*10} + ${E.fmt(q.a)} × ${q.b%10} = ${E.fmt(q.answer)}.`;return `Cherche le nombre qui, multiplié par ${q.b}, donne ${q.a} : ${q.answer} × ${q.b} = ${q.a}.`;}
 async function submit(expired=false){
  const g=game;if(!g||g.paused||g.done||apiPending)return;
  const doom=g.config.track==='doom',elapsed=seconds();
  const value=expired||(doom&&elapsed>=30)?null:E.parse($('#answer').value);
  if(value===null&&!expired&&!(doom&&elapsed>=30)){$('#feedback').innerHTML='<div class="feedback">Écris un nombre, avec une virgule si besoin.</div>';return;}
  const q=g.questions[g.index];let timedOut=doom&&(expired||elapsed>=30);
  if(g.remote){apiPending=true;$('#answer').disabled=true;
    try {const result=await api('games/'+g.remote+'/answer',{index:g.index,value});q.answer=result.answer;g.serverResult=result;timedOut=result.timedOut;}
    catch(e){g.remote=null;g.sharedFailed=true;toast('Connexion interrompue : termine cette partie en local.');AppLog.log('warning','Défi commun interrompu',e.message);q.answer=E.solve(q);}
    finally{apiPending=false;}
  }
  const correct=g.serverResult?g.serverResult.correct:!timedOut&&value===q.answer;
  g.tries++;if(g.tries===1)g.first={value,correct,timedOut,seconds:g.serverResult?.seconds??Math.min(doom?30:Infinity,elapsed)};
  if(!correct&&g.config.mode==='practice'&&g.tries===1){A.sound('error');g.input='';g.feedback='<div class="feedback bad"><strong>Essaie encore, tu peux y arriver.</strong><p>Tu peux aussi afficher la correction.</p><button type="button" id="show-answer">Voir la correction</button></div>';renderGame();$('#show-answer').onclick=()=>complete(false);return;}
  complete(correct);
 }
 function complete(correct){const g=game,q=g.questions[g.index];if(g.done)return;g.elapsed+=performance.now()-g.tick;g.done=true;g.holdNext=g.config.track!=='doom'&&(!g.first.correct||L.prefs.steps);g.combo=g.first.correct?g.combo+1:0;g.maxCombo=Math.max(g.maxCombo,g.combo);const gain=g.serverResult?g.serverResult.gain:g.config.mode==='challenge'?E.points(g.first.correct,g.config.track==='junior'?60:g.first.seconds,g.combo):0;g.score+=gain;g.serverResult=null;A.sound(g.config.track==='doom'?'doom':correct?'success':'error');g.autoRemaining=5000;g.autoTick=performance.now();if(!g.first.correct&&g.config.mode==='practice'&&!g.review&&!g.config.activity&&!q.spaced&&!g.scheduled.has(P.key(q))){g.scheduled.add(P.key(q));g.questions.splice(Math.min(g.index+4,g.questions.length),0,{...q,spaced:true});}const oldError=profile().errors.some(e=>e.label===q.label);if(correct&&oldError)g.repaired.push(q.label);g.answers.push({...q,...g.first,aided:!!g.hintIndex||!!g.toolUsed,corrected:correct,activeSeconds:g.config.track==='doom'?g.first.seconds:seconds(),gain});g.feedback=`<div class="feedback ${correct?'good':'bad'}"><strong>${g.first.timedOut?'Temps écoulé !':correct?(g.first.correct?'Bien joué !':'Tu as trouvé, bravo !'):'On apprend aussi en se trompant.'}${gain?` +${gain} pts`:''}</strong><p>${q.complement?`${q.a} + ${q.answer} = 20`:`${escape(q.label)} = <strong>${E.fmt(q.answer)}</strong>`}</p>${!g.first.correct?`<p>${tip(q)}</p>`:''}</div>`;if(document.hidden)freeze();renderGame();}
 async function next(){if(!game?.done||apiPending)return;const g=game;if(g.index===g.questions.length-1){finish();return;}apiPending=true;
  try {if(L.prefs.adaptive&&g.config.mode==='practice'&&!g.config.activity&&!g.review&&!g.config.table&&!g.questions[g.index+1]?.spaced){const current=g.questions[g.index].level||g.config.level,level=L.adjustedLevel(g.answers.slice(g.adaptiveSince||0),current);const previous=g.questions[g.index+1];if(level!==(previous.level||g.config.level)){const choices=E.generate({...g.config,category:previous.op,level,count:20});const candidate=choices.find(q=>!g.questions.some(old=>old.label===q.label));if(candidate){g.questions[g.index+1]=candidate;if(level!==current)g.adaptiveSince=g.answers.length;g.adaptiveNotice=level==='easy'||(current==='hard'&&level==='medium')?'On consolide avec des nombres plus simples.':'Tu progresses : essaie ce petit défi !';}}}if(g.remote){const data=await api('games/'+g.remote+'/next',{index:g.index});g.questions[g.index+1]=data.question;}Object.assign(g,{index:g.index+1,elapsed:0,tick:performance.now(),tries:0,feedback:null,first:null,correctionIndex:0,hintIndex:0,toolUsed:false,holdNext:false,input:'',done:false,autoTick:null});renderGame();}
  catch(e){g.remote=null;g.sharedFailed=true;toast('Connexion interrompue : la suite sera enregistrée en local.');Object.assign(g,{index:g.index+1,elapsed:0,tick:performance.now(),tries:0,feedback:null,first:null,hintIndex:0,toolUsed:false,holdNext:false,input:'',done:false,autoTick:null});renderGame();}finally{apiPending=false;if(document.hidden&&game&&!game.paused)togglePause();}}
 function finish(){if(game.config.activity==='coop'){finishCoop(game);return;}const g=game,p=profile(),s=p.stats,before=Math.floor(p.stars/10),oldMission=p.mission.claimed;const progress=P.update(p,g),correct=progress.correct,duration=g.answers.reduce((sum,a)=>sum+a.activeSeconds,0);let newRecord=false;
  if(g.config.mode==='challenge'){if(correct===10&&g.config.track!=='doom')s.perfect++;const score={score:g.score,correct,duration,category:g.config.category,level:g.config.level,table:g.config.table,track:g.config.track,date:new Date().toISOString()};const same=p.records.filter(x=>(x.track||'cm1')===score.track&&x.category===score.category&&x.level===score.level&&(x.table||'')===score.table).sort(rank);newRecord=!!same.length&&rank(score,same[0])<0;if(newRecord&&g.config.track!=='doom')s.records++;p.records.push(score);const groups={};for(const r of p.records){const key=[r.track||'cm1',r.category,r.level,r.table||''].join(':');(groups[key]??=[]).push(r);}p.records=Object.values(groups).flatMap(rs=>rs.sort(rank).slice(0,10));}
  const earned=g.config.track==='doom'?0:3+(correct/progress.total>=.8?1:0)+(g.review&&progress.repaired?1:0);p.stars+=earned;const newBadges=[];for(const [key,,title,,value,target]of badgeDefs)if(g.config.track!=='doom'&&!p.badges.includes(key)&&value(s)>=target){p.badges.push(key);newBadges.push(title);}
  last={...g,correct,total:progress.total,duration,earned,newBadges,newRecord,missionReward:!oldMission&&p.mission.claimed,accessory:Math.floor(p.stars/10)>before&&before<accessories.length};save();game=null;view='results';render();A.finish(newBadges.length>0);if(correct>0)confetti();}
 function results(){if(last?.coop){coopResults();return;}if(!last){view='home';render();return;}const l=last;app.innerHTML=`<section class="results"><div class="celebrate results-friend">${profile()?portrait(profile()):`<span style="font-size:60px">${l.correct===l.total?'🏆':'🌟'}</span>`}</div>${head(l.correct===l.total?'Un sans-faute, bravo !':'Une aventure de plus !','Chaque séance te fait progresser.')}<section class="panel">${l.answers?.length&&l.answers.length<=20?`<div class="verre-recap" role="list" aria-label="Tes calculs">${l.answers.map((a,i)=>`<span role="listitem" class="${a.correct?'ok':'retry'}" aria-label="Calcul ${i+1} : ${a.correct?'réussi':'repris'}">${i+1}</span>`).join('')}</div>`:''}<div class="big">${l.correct}<span style="font-size:30px;color:var(--muted)"> / ${l.total}</span></div><p>calculs réussis dès le premier essai</p><details class="result-method"><summary>Comment lire ce bilan ?</summary><p>Les révisions espacées ne sont pas incluses dans ce total. Les essais avec un indice sont comptés et signalés dans le détail.</p></details>${l.missionReward?'<p class="feedback good">🎯 Mission accomplie : +2 étoiles !</p>':''}${l.sharedFailed?'<p class="feedback bad">Connexion interrompue : résultat conservé localement. Vérifie le classement commun si la coupure a eu lieu à la dernière réponse.</p>':''}${l.remote?'<p class="feedback good">Résultat transmis au classement commun.</p>':''}<div class="statrow">${l.config.track==='doom'?'':`<div class="stat"><strong>+${l.earned} ⭐</strong><span>étoiles gagnées</span></div>`}${l.config.mode==='challenge'?`<div class="stat"><strong>${l.score}</strong><span>points${l.newRecord?' · Record battu !':''}</span></div>`:''}<div class="stat"><strong>${l.maxCombo}</strong><span>réponses de suite</span></div></div>${l.newBadges.length?`<p class="feedback good">🏅 ${l.newBadges.map(escape).join(' · ')}</p>`:''}${l.accessory?'<p class="feedback">🎁 Un nouvel accessoire t’attend dans ta collection !</p>':''}<div class="actions">${l.config.track!=='doom'&&profile().errors.length?'<button id="review" class="primary">Revoir mes erreurs</button>':''}<button id="replay" ${profile().errors.length?'':'class="primary"'}>Rejouer</button><button data-view="home">Accueil</button></div><section class="session-understood"><h2>Ce que tu as travaillé</h2><ul>${L.sessionSummary(l.answers).map(row=>`<li>${row.correct} ${row.correct===1?row.label.slice(0,-1):row.label} ${row.correct===1?'réussie':'réussies'} sur ${row.total}${row.aided?` · ${row.aided} avec aide`:``}.</li>`).join('')}</ul><p>${l.answers.some(a=>!a.correct&&!a.spaced)?`À revoir : ${escape(l.answers.find(a=>!a.correct&&!a.spaced).label)}. Tu peux le retravailler dans une prochaine séance.`:'Tu as consolidé ces calculs. Prêt pour une petite séance demain ?'}</p><button id="result-daily">Ma prochaine séance</button></section><h2>Ta séance en détail</h2><div class="table-wrap"><table><thead><tr><th>Calcul</th><th>Ta réponse</th><th>Solution</th><th>Bilan</th></tr></thead><tbody>${l.answers.map(a=>`<tr><td>${escape(a.label)}${a.aided?' (avec indice)':''}${a.spaced?' (révision)':''}</td><td>${a.timedOut?'Temps écoulé':E.fmt(a.value)}</td><td>${E.fmt(a.answer)}</td><td class="${a.correct?'correct':'incorrect'}">${a.correct?'✓ Réussi':a.corrected?'↻ Corrigé':'À revoir'}</td></tr>`).join('')}</tbody></table></div></section></section>`;$('#result-daily').onclick=()=>start(null,{...l.config,mode:'practice',activity:'daily',category:'mix',table:'',count:5});$('#replay').onclick=()=>start(null,l.config);if($('#review'))$('#review').onclick=()=>start(profile().errors);}
 function confetti(){if(L.prefs.calm)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const div=document.createElement('div');div.className='confetti';div.setAttribute('aria-hidden','true');for(let i=0;i<35;i++){const bit=document.createElement('i');bit.style.left=`${Math.random()*100}%`;bit.style.animationDelay=`${Math.random()*.5}s`;div.append(bit);}document.body.append(div);setTimeout(()=>div.remove(),2800);}

 function missionCard(p){const m=p.mission;return `<section class="panel small-panel"><h3>🎯 Ta mission du moment</h3><p>${m.title}</p><progress max="${m.target}" value="${m.progress}" aria-label="Progression de la mission"></progress><p>${m.claimed?'✓ Accomplie ! +2 étoiles':`${m.progress} / ${m.target} · +2 étoiles à gagner`}</p><button id="change-mission">${m.claimed?'Choisir une nouvelle mission':'Changer de mission'}</button></section>`;}
 function bindMission(){if($('#change-mission'))$('#change-mission').onclick=()=>{const p=profile(),i=P.missions.findIndex(m=>m.id===p.mission.id);p.mission=P.cleanMission(P.missions[(i+1)%P.missions.length]);save();home();};}
 function suggestion(p){const sessions=p.history.filter(h=>h.track===config.track&&h.category===config.category&&h.level===config.level).slice(-3);if(sessions.length<3)return '';const answers=sessions.flatMap(h=>h.answers.filter(a=>!a.spaced));const ratio=answers.filter(a=>a.correct).length/answers.length;const level=ratio>=.9?{easy:'medium',medium:'hard'}[config.level]:ratio<.5?{hard:'medium',medium:'easy'}[config.level]:null;return level?`<div class="feedback">Sur tes trois dernières séances, ${Math.round(ratio*100)} % de bonnes réponses. Tu peux essayer le niveau ${E.levels[level].toLowerCase()}. <button id="suggest-level" data-level="${level}">Choisir ${E.levels[level]}</button></div>`:'';}
 function trophies(p){const labels={add:'Additions',sub:'Soustractions',mul:'Multiplications',div:'Divisions'};return `<h2 class="spaced">Tes trophées · les réussites s’accumulent</h2><div class="grid">${Object.entries(labels).flatMap(([op,title])=>{const n=p.stats.opCorrect?.[op]||0;return [10,50,100].map((target,i)=>`<article class="panel badge ${n>=target?'':'locked'}"><span class="badge-icon badge-picture trophy-picture"><img src="assets/trophies/${op}-${['bronze','argent','or'][i]}.png" width="112" height="112" alt="" loading="lazy">${n>=target?'':'<span class="badge-lock" aria-hidden="true">🔒</span>'}</span><h3>${title} · ${['Bronze','Argent','Or'][i]}</h3><p>${Math.min(n,target)} / ${target} réponses réussies</p><span class="tag">${n>=target?'Gagné !':'En progression'}</span></article>`);}).join('')}</div>`;}
 function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function settings(){const p=profile(),prefs=A.prefs;app.innerHTML=`${head('À ta façon','Le son, le rythme et tes sauvegardes.')}<div class="grid settings-grid">${L.settingsHtml()}${N.settingsHtml()}<section class="panel"><h2>🎵 Musique et sons</h2><label class="check"><input id="music-enabled" type="checkbox" ${prefs.music?'checked':''}> Musique de fond</label><label>Volume de la musique<input id="music-volume" type="range" min="0" max="100" value="${Math.round(prefs.musicVolume*100)}"></label><label class="check"><input id="effects-enabled" type="checkbox" ${prefs.effects?'checked':''}> Effets sonores</label><label>Volume des effets<input id="effects-volume" type="range" min="0" max="100" value="${Math.round(prefs.effectsVolume*100)}"></label><p class="muted">Le bouton haut-parleur coupe tous les sons. La musique commence après une interaction.</p></section><section class="panel"><h2>⏱ Ton rythme</h2><label class="check"><input id="auto-next" type="checkbox" ${L.prefs.autoNext?'checked':''}> Question suivante après 5 secondes</label><p>Le bouton « Question suivante » reste disponible. Après une erreur ou une correction détaillée, tu continues quand tu veux. Ce choix est propre à ton profil.</p><h2>🌍 Classement commun</h2><label class="check"><input id="shared" type="checkbox" ${p.shared?'checked':''}> Publier mes prochains défis</label><p>Ton pseudo <strong>${escape(p.name)}</strong>, tes résultats et leur date seront visibles des autres joueurs. Seuls les défis joués avec cette option sont envoyés.</p><p id="shared-status" role="status"></p></section><section class="panel"><h2>💾 Sauvegarder mes profils</h2><button id="export-profiles" class="primary">Exporter tous les profils</button><label class="spaced">Importer une sauvegarde<input id="import-profiles" type="file" accept=".json,application/json"></label><p>Les profils importés sont ajoutés comme de nouveaux profils locaux. Aucun profil existant n’est remplacé. Les identités du classement commun ne sont pas exportées.</p><p id="import-status" role="status"></p></section></div>`;
  N.bindSettings(app,()=>L.apply());L.bindSettings(app);
  $('#music-enabled').onchange=e=>A.set({music:e.target.checked});$('#effects-enabled').onchange=e=>A.set({effects:e.target.checked});$('#music-volume').oninput=e=>A.set({musicVolume:Number(e.target.value)/100});$('#effects-volume').oninput=e=>A.set({effectsVolume:Number(e.target.value)/100});$('#auto-next').onchange=e=>L.set({autoNext:e.target.checked});
  $('#shared').onchange=async e=>{const input=e.target;input.disabled=true;const status=$('#shared-status');try{if(input.checked){if(!auth[p.id]){const r=await api('players',{});auth[p.id]=r.token;saveAuth();}else await api('health');}p.shared=input.checked;save();status.textContent=p.shared?'Les prochains défis participeront au classement commun.':'Participation désactivée. Les résultats déjà publiés restent dans le classement.';}catch(err){input.checked=false;p.shared=false;save();status.textContent=err.message;}finally{input.disabled=false;}};
  $('#export-profiles').onclick=()=>download('mathelio-profils-'+new Date().toISOString().slice(0,10)+'.json',{app:'Mathelio',version:2,profiles:state.profiles.map(P.cleanProfile)});
  $('#import-profiles').onchange=async e=>{const status=$('#import-status');try{const file=e.target.files[0];if(!file)return;if(file.size>20000000)throw Error('Fichier trop volumineux (20 Mo maximum).');const data=JSON.parse(await file.text());if(data.app!=='Mathelio'||data.version!==2||!Array.isArray(data.profiles)||!data.profiles.length)throw Error('Ce fichier n’est pas une sauvegarde Mathélio v2.');if(state.profiles.length+data.profiles.length>12)throw Error('12 profils maximum : cette sauvegarde dépasse la limite.');const imported=data.profiles.map(P.cleanProfile).map(p=>({...p,id:id(),shared:false}));state.profiles.push(...imported);save();status.textContent=`${imported.length} profil(s) ajouté(s). Retrouve-les dans Mon profil.`;}catch(err){status.textContent='Import impossible : '+err.message;AppLog.log('warning','Import refusé',err.message);}};
 }
 function parent(){const p=profile();app.innerHTML=`${head('Le bilan de '+escape(p.name),'La précision au premier essai, y compris les réponses avec indice ; reprises espacées exclues.')}<section class="panel"><label>Parcours<select id="parent-track">${selectOptions(schoolTracks,config.track)}</select></label><div id="parent-content"></div></section><div id="mini-parent-content"></div><p class="muted">Ce bilan est accessible sur cet appareil, sans mot de passe. Il utilise les 200 dernières séances enregistrées depuis la version 2.</p>`;$('#parent-track').value=config.track;
  const draw=()=>{const miniLevel=$('#parent-track').value==='junior'?'cp':$('#parent-track').value;$('#mini-parent-content').innerHTML=MiniProgress.parentHtml(miniLevel);app.querySelectorAll('[data-mini-recommend]').forEach(b=>b.onclick=()=>{const id=b.dataset.miniRecommend,level=b.dataset.miniLevel;setView('minigames');const link=app.querySelector('[data-mini="'+id+'"]:not([data-daily])');if(link){link.dataset.level=level;link.click();}});const sessions=p.history.filter(h=>h.track===$('#parent-track').value),answers=sessions.flatMap(h=>h.answers.filter(a=>!a.spaced));const pending=p.errors.filter(q=>q.track===$('#parent-track').value);const rows=Object.entries(E.categories).filter(([op])=>op!=='mix').map(([op,label])=>{const a=answers.filter(a=>a.op===op),n=a.filter(a=>a.correct).length;return `<tr><td>${label}</td><td>${a.length}</td><td>${a.length?Math.round(n/a.length*100)+' %':'—'}</td></tr>`;}).join('');const tables=Array.from({length:['ce1','ce2'].includes($('#parent-track').value)?9:11},(_,i)=>i+2).map(n=>{const a=answers.filter(a=>a.op==='mul'&&a.b===n);return a.length&&a.filter(a=>a.correct).length/a.length<.8?`Table de ${n}`:null;}).filter(Boolean);$('#parent-content').innerHTML=sessions.length?`<h2 class="spaced">Précision par opération</h2><div class="table-wrap"><table><thead><tr><th>Opération</th><th>Calculs</th><th>Réussite</th></tr></thead><tbody>${rows}</tbody></table></div>${pending.length?`<section class="parent-revisions"><h2>Les calculs à revoir</h2><p>${[...new Set(pending.slice(-5).map(a=>a.label))].map(escape).join(' · ')}</p><button id="parent-review">Revoir ces calculs</button></section>`:''}<h2 class="spaced">Tables à retravailler</h2><p>${tables.length?tables.join(' · '):'Aucune table sous 80 % de réussite parmi celles travaillées.'}</p><h2 class="spaced">Les 10 dernières séances</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Activité</th><th>Niveau</th><th>Réussite</th></tr></thead><tbody>${sessions.slice(-10).reverse().map(h=>{const a=h.answers.filter(a=>!a.spaced);return `<tr><td>${new Date(h.date).toLocaleDateString('fr-FR')}</td><td>${E.categories[h.category]}</td><td>${E.levels[h.level]}</td><td>${a.filter(x=>x.correct).length} / ${a.length}</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="empty">Les premières séances de ce parcours apparaîtront ici.</p>';if($('#parent-review'))$('#parent-review').onclick=()=>{chooseTrack($('#parent-track').value);config.category='mix';const questions=[...new Map(pending.slice(-20).map(a=>[P.key(a),P.cleanQuestion(a)])).values()];start(questions,{...config,mode:'practice'});};};$('#parent-track').onchange=draw;draw();
 }
 for(let table=2;table<=10;table++)badgeDefs.push(['table'+table,'✖️','Table de '+table,`Réussir 20 multiplications de la table de ${table}.`,s=>s.tables[table]||0,20]);
 badgeDefs.push(['junior','🐣','Petit explorateur','Terminer 5 séances du parcours 5–6 ans.',s=>s.junior||0,5],['complement','🧩','Le compte est bon','Réussir 20 compléments à 20.',s=>s.complements||0,20],['mission','🎯','Mission accomplie','Terminer 3 missions.',s=>s.missions||0,3]);
 function muteLabel(){const b=$('#mute');b.textContent=A.prefs.muted?'🔇':'🔊';b.setAttribute('aria-label',A.prefs.muted?'Réactiver le son':'Couper le son');b.setAttribute('aria-pressed',A.prefs.muted);}
 $('#mute').onclick=()=>A.set({muted:!A.prefs.muted});document.addEventListener('preferenceschange',muteLabel);muteLabel();

 function doom(){app.innerHTML=`<section class="doom-intro panel"><p class="eyebrow">Mode secret · Pour les parents</p><h1>DOOM</h1><p class="doom-subtitle">Le calcul mental passe en mode extrême.</p><div class="statrow"><div class="stat"><strong>10</strong><span>calculs</span></div><div class="stat"><strong>30 s</strong><span>par question</span></div><div class="stat"><strong>2 à 5</strong><span>nombres à combiner</span></div></div><p>Additions, soustractions, multiplications. Respectez les parenthèses.</p><p>Le temps continue pendant les questions, même en arrière-plan. À zéro : correction et question suivante. Scores séparés, sans modifier les progrès de l’enfant.</p><div class="actions"><button id="start-doom" class="primary">Entrer dans Doom</button><button data-view="home">Retour au calme</button></div></section>`;$('#start-doom').onclick=()=>start(null,{track:'doom',category:'mix',level:'hard',table:'',mode:'challenge',count:10});}
 $('#secret-logo').onclick=()=>{if(game||starting||apiPending)return;const now=performance.now();logoClicks=now-lastLogoClick<2000?logoClicks+1:1;lastLogoClick=now;if(logoClicks===5){logoClicks=0;if(!profile()){toast('Crée un profil avant de relever le défi.');return;}doomUnlocked=true;setView('doom');A.enterDoom();}};
 document.addEventListener('click',e=>{const button=e.target.closest('[data-view]');if(button){e.preventDefault();setView(button.dataset.view);}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&!game.paused&&!apiPending)togglePause();if(!document.hidden&&game?.config.track==='doom'&&!game.done&&seconds()>=30)submit(true);});
 addEventListener('beforeunload',e=>{if(game){e.preventDefault();e.returnValue='';}});
 setInterval(()=>{
  const g=game;if(view!=='game'||!g||g.paused||apiPending)return;
  if(!g.done){const elapsed=seconds();if($('#timer'))$('#timer').textContent=(g.config.track==='doom'?Math.max(0,30-elapsed):elapsed).toFixed(1);if(g.config.track==='doom'&&elapsed>=30){submit(true);return;}}
  if(document.hidden)return;
  if(g.done&&!g.holdNext&&L.autoNext(A.prefs,g.config.track)){const now=performance.now();if(g.autoTick)g.autoRemaining=Math.max(0,g.autoRemaining-(now-g.autoTick));g.autoTick=now;if($('#countdown'))$('#countdown').textContent='Suite dans '+Math.ceil(g.autoRemaining/1000)+' s';if(g.autoRemaining<=0)next();}
 },100);
 addEventListener('storage',e=>{if(e.key===KEY){state.readOnly=true;$('#storage-warning').hidden=false;$('#storage-warning').textContent='Un autre onglet a modifié les profils. Recharge cette page avant de continuer pour éviter de remplacer tes progrès.';}});
 const destination=location.hash.slice(1);if(['home','minigames','collection','records','parent','settings','profiles'].includes(destination))view=destination;else if(state.profiles.length>1&&(()=>{try{return !sessionStorage.getItem('mathelio.chosen');}catch{return false;}})()){view='profiles';document.body.classList.add('who-plays');}
 render();
})();
